def getHappyString(n: int, k: int) -> str:
    def backtrack(path, used):
        if len(path) == n:
            happy_strings.append(''.join(path))
            return
        for c in ['a', 'b', 'c']:
            if not path or c != path[-1]:
                backtrack(path + [c], used | {c})

    happy_strings = []
    backtrack([], set())
    happy_strings.sort()
    return happy_strings[k-1] if k <= len(happy_strings) else ""
